@startuml

class City {
  + Name : string
}

class H2SLocation {
  + LocationID : int
}

class Resident {
  + Name : string
  + StreetAddress : string
  + PhoneNumber : string
  + Email : string
  + ItemDescription : string
}

class PickupRequest {
  + RequestedDate : date
  + RequestedTime : time
}

class Vehicle {
  + LicensePlate : string
  + StorageCapacity : float
}

class VolunteerDriver {
  + Name : string
  + AvailableDays : string[]
}

class PickupRoute {
  + RouteDate : date
}

class ScheduledItem {
  + Weight : float
  + Dimensions : string
}

class DistributionCenter {
  + Address : string
}

class FoodBank {
  + Address : string
}

class H2SEmployee {
  + EmployeeID : int
  + Name : string
}

class Article {
  + RFIDTag : string
  + Description : string
  + Category : string
}

class Category {
  + CategoryName : string
}

class Client {
  + Name : string
  + HomeAddress : string
  + NeededCategories : string[]
}

City "1" -- "*" H2SLocation
H2SLocation "1" -- "*" DistributionCenter
H2SLocation "1" -- "*" FoodBank
Resident "1" -- "*" PickupRequest
PickupRequest "1" -- "1" ScheduledItem
Vehicle "1" -- "*" PickupRoute
VolunteerDriver "1" -- "*" PickupRoute
PickupRoute "1" -- "*" ScheduledItem
DistributionCenter "1" -- "*" Article
DistributionCenter "1" -- "*" FoodBank
H2SEmployee "1" -- "*" Article
Article "*" -- "1" Category
Client "1" -- "*" Article
H2SEmployee "1" -- "*" Client

@enduml

